const item = $input.item.json;
const platform = item.platform;
const postId = item.platform_post_id;
let metrics = { impressions: 0, reach: 0, likes: 0, comments: 0, shares: 0, saves: 0, clicks: 0 };

async function getCred(plat) {
  const cred = await this.helpers.httpRequest({
    method: 'GET',
    url: `${$env.API_BASE_URL}/api/businesses/${item.business_id}/credentials`,
    headers: { 'Authorization': `Bearer ${$env.ENGINE_JWT}` },
  });
  return cred?.find(c => c.platform === plat);
}

try {
  if (platform === 'instagram') {
    const c = await getCred.call(this, 'instagram');
    if (c?.access_token) {
      const res = await this.helpers.httpRequest({ method: 'GET', url: `https://graph.facebook.com/v21.0/${postId}/insights?metric=impressions,reach,likes,comments,saved,shares&access_token=${c.access_token}` });
      for (const m of (res?.data || [])) {
        if (m.name === 'impressions') metrics.impressions = m.values?.[0]?.value || 0;
        if (m.name === 'reach') metrics.reach = m.values?.[0]?.value || 0;
        if (m.name === 'likes') metrics.likes = m.values?.[0]?.value || 0;
        if (m.name === 'comments') metrics.comments = m.values?.[0]?.value || 0;
        if (m.name === 'saved') metrics.saves = m.values?.[0]?.value || 0;
        if (m.name === 'shares') metrics.shares = m.values?.[0]?.value || 0;
      }
    }
  } else if (platform === 'facebook') {
    const c = await getCred.call(this, 'facebook');
    if (c?.access_token) {
      const res = await this.helpers.httpRequest({ method: 'GET', url: `https://graph.facebook.com/v21.0/${postId}?fields=shares,reactions.summary(true),comments.summary(true)&access_token=${c.access_token}` });
      metrics.shares = res?.shares?.count || 0;
      metrics.likes = res?.reactions?.summary?.total_count || 0;
      metrics.comments = res?.comments?.summary?.total_count || 0;
    }
  } else if (platform === 'youtube') {
    if ($env.YOUTUBE_API_KEY) {
      const res = await this.helpers.httpRequest({ method: 'GET', url: `https://www.googleapis.com/youtube/v3/videos?id=${postId}&part=statistics&key=${$env.YOUTUBE_API_KEY}` });
      const stats = res?.items?.[0]?.statistics || {};
      metrics.impressions = parseInt(stats.viewCount || 0);
      metrics.likes = parseInt(stats.likeCount || 0);
      metrics.comments = parseInt(stats.commentCount || 0);
    }
  } else if (platform === 'tiktok') {
    const c = await getCred.call(this, 'tiktok');
    if (c?.access_token) {
      const res = await this.helpers.httpRequest({ method: 'POST', url: 'https://open.tiktokapis.com/v2/video/query/', headers: { 'Authorization': `Bearer ${c.access_token}`, 'Content-Type': 'application/json' }, body: JSON.stringify({ filters: { video_ids: [postId] }, fields: ['like_count', 'comment_count', 'share_count', 'view_count'] }) });
      const video = res?.data?.videos?.[0] || {};
      metrics.impressions = video.view_count || 0;
      metrics.likes = video.like_count || 0;
      metrics.comments = video.comment_count || 0;
      metrics.shares = video.share_count || 0;
    }
  } else if (platform === 'x') {
    // X metrics require Basic tier ($200/mo) — uses Bearer token
    if ($env.X_BEARER_TOKEN) {
      const res = await this.helpers.httpRequest({ method: 'GET', url: `https://api.x.com/2/tweets/${postId}?tweet.fields=public_metrics`, headers: { 'Authorization': `Bearer ${$env.X_BEARER_TOKEN}` } });
      const pm = res?.data?.public_metrics || {};
      metrics.impressions = pm.impression_count || 0;
      metrics.likes = pm.like_count || 0;
      metrics.comments = pm.reply_count || 0;
      metrics.shares = pm.retweet_count || 0;
      metrics.saves = pm.bookmark_count || 0;
    }
  } else if (platform === 'linkedin') {
    // LinkedIn org share statistics — works for Company Page posts
    const c = await getCred.call(this, 'linkedin');
    if (c?.access_token) {
      const res = await this.helpers.httpRequest({ method: 'GET', url: `https://api.linkedin.com/v2/socialActions/${postId}`, headers: { 'Authorization': `Bearer ${c.access_token}` } });
      metrics.likes = res?.likesSummary?.totalLikes || 0;
      metrics.comments = res?.commentsSummary?.totalFirstLevelComments || 0;
      metrics.shares = res?.sharesSummary?.totalShares || 0;
    }
  }
} catch(e) {
  console.log(`[engagement] Error fetching ${platform} metrics: ${e.message}`);
}

return [{ json: { content_id: item.content_id, platform: item.platform, platform_post_id: item.platform_post_id, ...metrics } }];
